DO $$ DECLARE def text;BEGIN SELECT pg_get_functiondef('public.finance_schedule_account(uuid,text,text,text)'::regprocedure) INTO def;def:=replace(def,'IF a IS NULL THEN','IF a IS NOT NULL AND NOT EXISTS(SELECT 1 FROM chart_of_accounts WHERE id=a AND account_type=k AND lower(name)=lower(n)) THEN RAISE EXCEPTION ''Account code % already has another purpose; review account setup'',c;END IF;IF a IS NULL THEN');EXECUTE def;
SELECT pg_get_functiondef('public.finance_schedule_prepare(uuid,date)'::regprocedure) INTO def;def:=replace(def,'a.expense_account_id IS NOT NULL AND a.accumulated_depr_account_id IS NOT NULL','a.expense_account_id IS NOT NULL AND a.accumulated_depr_account_id IS NOT NULL AND EXISTS(SELECT 1 FROM chart_of_accounts WHERE id=a.expense_account_id AND code=''6900'' AND lower(name) LIKE ''%depreciation%'') AND EXISTS(SELECT 1 FROM chart_of_accounts WHERE id=a.accumulated_depr_account_id AND code=''1550'') AND NOT EXISTS(SELECT 1 FROM fixed_asset_depreciation_schedule WHERE asset_id=a.id AND period_year=extract(year FROM m) AND period_month=extract(month FROM m) AND status=''posted'')');EXECUTE def;
SELECT pg_get_functiondef('public.finance_schedule_approve(uuid,uuid,date)'::regprocedure) INTO def;def:=replace(def,'IF q.source_data ? ''item'' THEN SELECT','IF q.kind IN(''tax'',''stock'',''grni'') THEN RAISE EXCEPTION ''Source revalidation not yet available for this draft kind; approval blocked'';END IF;IF q.source_data ? ''item'' THEN SELECT');EXECUTE def;
SELECT pg_get_functiondef('public.finance_reconciliation_rows(uuid,date)'::regprocedure) INTO def;def:=replace(def,'AND a.code=ANY(r.codes)','AND (CASE WHEN r.key=''accruals'' THEN lower(a.name)=''accrued expenses'' ELSE a.code=ANY(r.codes) END)');EXECUTE def;END $$;
CREATE FUNCTION public.finance_opening_asset(t uuid,p jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a uuid;asset uuid;accum uuid;expense uuid;equity uuid;cost numeric:=(p->>'cost')::numeric;depr numeric:=coalesce((p->>'opening_depreciation')::numeric,0);BEGIN
IF NOT finance_schedule_manager(t) THEN RAISE EXCEPTION 'Owner or admin required';END IF;IF cost<=0 OR depr<0 OR depr>cost OR (p->>'life_months')::int<=0 THEN RAISE EXCEPTION 'Invalid asset values';END IF;
asset:=finance_schedule_account(t,'1500','Fixed Assets','asset');accum:=finance_schedule_account(t,'1550','Accumulated Depreciation','asset');expense:=finance_schedule_account(t,'6900','Depreciation Expense','opex');SELECT id INTO equity FROM chart_of_accounts WHERE tenant_id=t AND id=(p->>'opening_account_id')::uuid AND account_type='equity';IF equity IS NULL THEN RAISE EXCEPTION 'Choose opening equity account';END IF;
INSERT INTO fixed_assets(tenant_id,asset_tag,name,category,purchase_date,in_service_date,cost,useful_life_months,venue,asset_account_id,accumulated_depr_account_id,expense_account_id,amount_remaining,notes,created_by) VALUES(t,'OPEN-'||gen_random_uuid()::text,p->>'name',p->>'category',(p->>'date')::date,(p->>'date')::date,cost,(p->>'life_months')::int,nullif(p->>'venue',''),asset,accum,expense,0,'Opening proposal awaiting approval',auth.uid()) RETURNING id INTO a;
PERFORM finance_schedule_enqueue(t,(p->>'date')::date,'asset_opening',p->>'name','Opening asset register and accumulated depreciation','asset-opening:'||a,jsonb_build_array(jsonb_build_object('account_id',asset,'debit',cost,'credit',0,'venue',nullif(p->>'venue','')),jsonb_build_object('account_id',accum,'debit',0,'credit',depr,'venue',nullif(p->>'venue','')),jsonb_build_object('account_id',equity,'debit',0,'credit',cost-depr,'venue',nullif(p->>'venue',''))),jsonb_build_object('asset',a,'opening_depreciation',depr));RETURN a;END $$;REVOKE ALL ON FUNCTION public.finance_opening_asset(uuid,jsonb) FROM PUBLIC;GRANT EXECUTE ON FUNCTION public.finance_opening_asset(uuid,jsonb) TO authenticated;
DO $$ DECLARE def text;BEGIN SELECT pg_get_functiondef('public.finance_schedule_approve(uuid,uuid,date)'::regprocedure) INTO def;def:=replace(def,'IF q.kind=''depreciation'' THEN UPDATE','IF q.kind=''asset_opening'' THEN UPDATE fixed_assets SET amount_depreciated=(q.source_data->>''opening_depreciation'')::numeric,amount_remaining=cost-(q.source_data->>''opening_depreciation'')::numeric,notes=''Approved opening asset'' WHERE id=(q.source_data->>''asset'')::uuid AND tenant_id=t;END IF;IF q.kind=''depreciation'' THEN UPDATE');EXECUTE def;
SELECT pg_get_functiondef('public.finance_schedule_prepare(uuid,date)'::regprocedure) INTO def;def:=replace(def,'AND in_service_date<=ending','AND in_service_date<=ending AND notes IS DISTINCT FROM ''Opening proposal awaiting approval''');EXECUTE def;END $$;